/// <summary>
/// CB166_SalesOrderSubstitutes
/// Batch service class for Post sales order creation processing
/// </summary>
class METSysMessageProcessorService extends SysOperationServiceBase
{
    Batch                           batchTaskCurrent;
    BatchHeader                     batchHeader;
    RefRecId                        batchJobId;
    RefRecId                        headerTaskId;
    boolean                         isExecutingInBatch;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METSysMessageProcessorContract _contract)
{
    batchTaskCurrent    = this.getCurrentBatchTask();
    batchJobId          = batchTaskCurrent.BatchJobId;
    headerTaskId        = batchTaskCurrent.RecId;
    batchHeader         = BatchHeader::construct(batchJobId);
    isExecutingInBatch  = batchTaskCurrent ? true : false;

    this.createTopPickingTasks(_contract);
}

private void createTopPickingTasks(METSysMessageProcessorContract _contract)
{
    SysOperationServiceController   controller;
    SysMessageQueue messageQueue = _contract.parmMessageQueue();
    SysMessageQueueMetadata messageQueueMetadata = SysMessageQueueMetadata::construct(messageQueue);
    METSysMessageProcessorContract taskDataContract;
    guid topPickingProcessId = newGuid();

    int maxTasks = messageQueueMetadata.getMessageProcessorsTasks();
    if (isExecutingInBatch)
    {
        for (int i = 1; i <= maxTasks; i++)
        {
            controller = new SysOperationServiceController(classStr(METSysMessageProcessorTaskService), methodStr(METSysMessageProcessorTaskService, process));
            controller.parmDialogCaption("MET Message processor - Top picking POC");

            // grab contract instance from controller, use same contract
            taskDataContract = controller.getDataContractObject();
            taskDataContract.parmMessageQueue(messageQueue);
            taskDataContract.parmIsMainBatchTask(i==1);
            taskDataContract.parmTopPickingProcessId(topPickingProcessId);

            //Bug 174941 - CB-166 Custom top picking batch jobs with recurrence keeps creating new batch tasks
            batchHeader.addRuntimeTask(controller, headerTaskId);
        }

        // Do not overwrite the user's batch job name from the class method
        // Was not there in old service classes from METPriceDataFeedService
        //batchHeader.parmCaption(this.getTaskServiceCaption());
        batchHeader.save();
    }
}
